static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    date_time s = {2022, 12, 31, 23, 30, 0}, o;
    assert(delivery_date(s, "NOW", &o) && o.year == 2023 && o.month == 1 &&
           o.day == 1 && o.hour == 1 && o.minute == 30);
    s = (date_time){2025, 1, 6, 12, 0, 0};
    assert(delivery_date(s, "EOW", &o) && o.day == 10 && o.hour == 17);
