    s.hour = 13;
    assert(delivery_date(s, "ASAP", &o) && o.day == 7 && o.hour == 13);
    assert(delivery_date(s, "2M", &o) && o.month == 2 && o.day == 3);
    assert(delivery_date(s, "Q1", &o) && o.month == 3 && o.day == 31);
